Error in `chromote_wait_for_condition(self$get_chromote_session(), script, timeout = timeout, interval = interval)`: Timed out waiting for JavaScript script to return `true`
i `timeout`: 30000
i `script`:
(() => {
  let el = document.getElementById("teal-teal_modules-nav-vitals-module-lab_values_table");
  if (!el) {
    const suffix = "lab_values_table";
    const selector = `[id='${suffix}'], [id$='-${suffix}']`;
    const candidates = Array.from(document.querySelectorAll(selector));
    el = candidates.find((node) => {
      if (node.classList.contains('shiny-bound-output')) return true;
      if (node.querySelector('table, .rtablesTable, .dataTables_wrapper')) return true;
      return false;
    }) || candidates[0] || null;
  }
  if (!el) return false;
  if (el.classList.contains('recalculating')) return false;
  if (el.querySelector('.shiny-output-error, .shiny-output-error-validation')) return false;
  const rowCount = el.querySelectorAll(
    'table tbody tr, .rtablesTable tbody tr, .dataTables_wrapper tbody tr, table tr'
  ).length;
  return rowCount >= 1;
})()
